// ============================================================
// js/itinerary.js – Itinerary Display Logic
// ============================================================
// This is the most complex JS file. It handles two modes:
//
//   MODE 1: ?new=true  → Load itinerary from sessionStorage
//           (just generated by the planner page)
//
//   MODE 2: ?id=xxx    → Fetch saved itinerary from the API
//           (viewing a saved trip from the dashboard)
//
// Then it renders the full itinerary UI:
//   - Trip hero banner with meta info
//   - Budget vs estimate bar
//   - Per-day cost table
//   - Day tabs for navigation
//   - Day cards with activity timeline, hotel, restaurants
//   - Travel tips
//   - Save button (if new)
// ============================================================

document.addEventListener('DOMContentLoaded', async () => {
  requireAuth();

  const params     = new URLSearchParams(window.location.search);
  const isNew      = params.get('new') === 'true';
  const tripId     = params.get('id');
  let   itinerary  = null;
  let   isSaved    = !isNew; // Already saved if loaded from DB

  // ── Load Itinerary Data ──────────────────────────────────
  if (isNew) {
    // Mode 1: From sessionStorage (just generated)
    const stored = sessionStorage.getItem('wanderai_current_itinerary');
    if (!stored) {
      showError('No itinerary data found. Please generate a new plan.');
      return;
    }
    itinerary = JSON.parse(stored);
    // Show save button
    document.getElementById('save-btn').style.display = 'inline-flex';
  } else if (tripId) {
    // Mode 2: From API (saved trip)
    document.getElementById('loading-state').style.display = 'block';
    try {
      const res  = await fetch(`${API_BASE}/itinerary/${tripId}`, {
        headers: getAuthHeader()
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Could not load itinerary');
      itinerary = data.itinerary;
      document.getElementById('loading-state').style.display = 'none';
      document.getElementById('saved-badge').style.display   = 'inline-flex';
    } catch (err) {
      showError(err.message);
      return;
    }
  } else {
    showError('Invalid page access. Please go to My Trips or Plan a Trip.');
    return;
  }

  // ── Render Everything ────────────────────────────────────
  renderItinerary(itinerary);

  // ── Save Button Handler ──────────────────────────────────
  document.getElementById('save-btn').addEventListener('click', async () => {
    const btn = document.getElementById('save-btn');
    btn.disabled = true;
    btn.innerHTML = `<div class="spinner"></div> Saving...`;

    try {
      const res  = await fetch(`${API_BASE}/itinerary/save`, {
        method:  'POST',
        headers: getAuthHeader(),
        body:    JSON.stringify(itinerary)
      });
      const data = await res.json();

      if (!res.ok) throw new Error(data.error || 'Save failed');

      isSaved = true;
      btn.style.display = 'none';
      document.getElementById('saved-badge').style.display = 'inline-flex';
      showToast('success', '💾 Saved!', 'Your itinerary has been saved to My Trips.');
      // Clear sessionStorage since it's now in the DB
      sessionStorage.removeItem('wanderai_current_itinerary');
    } catch (err) {
      showToast('error', 'Save Failed', err.message);
      btn.disabled = false;
      btn.innerHTML = '💾 Save Itinerary';
    }
  });
});

// ── Main Render Function ──────────────────────────────────
function renderItinerary(data) {
  const plan      = data.generatedPlan || [];
  const summary   = data.summary || {};

  document.getElementById('itinerary-content').style.display = 'block';

  // Hero section
  document.getElementById('destination-badge').innerHTML = `📍 ${data.destination}`;
  document.getElementById('itinerary-title').textContent  = `${data.destination} Itinerary`;
  document.getElementById('itinerary-overview').textContent = summary.overview || '';

  // Meta info grid
  const startDate = new Date(data.startDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  const endDate   = new Date(data.endDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  const days      = plan.length;
  document.getElementById('trip-meta-grid').innerHTML = `
    <div class="meta-item"><div class="meta-label">📅 Start</div><div class="meta-value">${startDate}</div></div>
    <div class="meta-item"><div class="meta-label">📅 End</div><div class="meta-value">${endDate}</div></div>
    <div class="meta-item"><div class="meta-label">⏱️ Duration</div><div class="meta-value">${days} day${days !== 1 ? 's' : ''}</div></div>
    <div class="meta-item"><div class="meta-label">👥 Travelers</div><div class="meta-value">${data.travelers}</div></div>
    <div class="meta-item"><div class="meta-label">💵 Budget</div><div class="meta-value">$${Number(data.budget).toLocaleString()}</div></div>
    ${summary.bestTimeToVisit ? `<div class="meta-item"><div class="meta-label">🌤️ Best Time</div><div class="meta-value" style="font-size:0.85rem;">${summary.bestTimeToVisit}</div></div>` : ''}
  `;

  // Expense summary
  renderExpenseSummary(data, plan, summary);

  // Travel tips
  if (summary.travelTips && summary.travelTips.length > 0) {
    document.getElementById('tips-section').style.display = 'block';
    document.getElementById('tips-grid').innerHTML =
      summary.travelTips.map(tip => `<div class="tip-card">${tip}</div>`).join('');
  }

  // Day tabs + day cards
  renderDayTabs(plan);
  renderAllDays(plan);
}

// ── Expense Summary ────────────────────────────────────────
function renderExpenseSummary(data, plan, summary) {
  const estimatedCost = summary.totalEstimatedCost ||
    plan.reduce((sum, d) => sum + (d.dailyCostEstimate || 0), 0);
  const budget = Number(data.budget);

  document.getElementById('expense-total').textContent  = `$${estimatedCost.toLocaleString()}`;
  document.getElementById('budget-display').textContent = `$${budget.toLocaleString()}`;

  const pct   = budget > 0 ? Math.min(Math.round((estimatedCost / budget) * 100), 100) : 0;
  const over  = estimatedCost > budget;
  const fill  = document.getElementById('budget-fill');

  setTimeout(() => { fill.style.width = `${pct}%`; }, 100);
  if (over) fill.classList.add('over');

  document.getElementById('budget-percent').textContent = `${pct}% of budget`;
  document.getElementById('budget-status').textContent  = over
    ? `⚠️ Exceeds budget by $${(estimatedCost - budget).toLocaleString()}`
    : `✅ Within budget — $${(budget - estimatedCost).toLocaleString()} remaining`;
  document.getElementById('budget-status').style.color = over ? 'var(--error)' : 'var(--success)';

  // Per-day cost tiles
  const table = document.getElementById('daily-cost-table');
  table.innerHTML = plan.map(day => `
    <div style="background:var(--bg-glass); border:1px solid var(--border); border-radius:var(--radius-md); padding:0.75rem; text-align:center;">
      <div style="font-size:0.7rem; text-transform:uppercase; letter-spacing:0.05em; color:var(--text-muted);">Day ${day.day}</div>
      <div style="font-size:1.1rem; font-weight:700; color:var(--accent); margin-top:0.25rem;">$${(day.dailyCostEstimate || 0).toLocaleString()}</div>
      <div style="font-size:0.7rem; color:var(--text-muted); margin-top:0.2rem;">${day.theme || ''}</div>
    </div>
  `).join('');
}

// ── Day Tabs ───────────────────────────────────────────────
function renderDayTabs(plan) {
  const container = document.getElementById('day-tabs');
  container.innerHTML = plan.map((day, i) => `
    <button
      class="day-tab ${i === 0 ? 'active' : ''}"
      onclick="switchDay(${i})"
      id="tab-${i}"
    >Day ${day.day}</button>
  `).join('');
}

function switchDay(index) {
  // Update tab styles
  document.querySelectorAll('.day-tab').forEach((tab, i) => {
    tab.classList.toggle('active', i === index);
  });
  // Show/hide day cards
  document.querySelectorAll('.day-card').forEach((card, i) => {
    card.style.display = i === index ? 'block' : 'none';
  });
}

// ── All Day Cards ──────────────────────────────────────────
function renderAllDays(plan) {
  const container = document.getElementById('days-container');
  container.innerHTML = plan.map((day, i) => renderDayCard(day, i)).join('');
  // Only show first day initially
  document.querySelectorAll('.day-card').forEach((card, i) => {
    card.style.display = i === 0 ? 'block' : 'none';
  });
}

function renderDayCard(day, index) {
  const activities = (day.activities || []).map(act => `
    <div class="timeline-item">
      <div class="timeline-dot"></div>
      <div class="timeline-time">${act.time || 'Activity'}</div>
      <div class="timeline-content">
        <h4>${act.activity || ''}</h4>
        <div class="timeline-meta">
          ${act.location ? `<span>📍 ${act.location}</span>` : ''}
          ${act.duration ? `<span>⏱️ ${act.duration}</span>` : ''}
          ${act.cost     ? `<span>💵 $${act.cost}</span>`    : ''}
        </div>
      </div>
    </div>
  `).join('');

  const hotel = day.hotel ? `
    <div class="hotel-card">
      <div style="display:flex; justify-content:space-between; align-items:flex-start;">
        <div>
          <h4>🏨 ${day.hotel.name}</h4>
          <p>${day.hotel.description || ''}</p>
          <div class="stars">${'⭐'.repeat(parseInt(day.hotel.rating) || 3)}</div>
        </div>
        <div class="hotel-price">$${day.hotel.pricePerNight || '?'}<span style="font-size:0.7rem; font-weight:400; color:var(--text-muted)">/night</span></div>
      </div>
    </div>
  ` : '<p style="color:var(--text-muted); font-size:0.85rem;">No hotel info available.</p>';

  const restaurants = (day.restaurants || []).map(r => `
    <div class="restaurant-card">
      <div class="restaurant-meal">${r.meal || 'Meal'}</div>
      <h4 style="font-size:0.9rem; margin-bottom:0.25rem;">🍽️ ${r.name}</h4>
      <p style="font-size:0.8rem; color:var(--text-secondary);">${r.cuisine || ''} cuisine</p>
      ${r.mustTry ? `<p style="font-size:0.78rem; color:var(--accent); margin-top:0.3rem;">✨ Try: ${r.mustTry}</p>` : ''}
      <p style="font-size:0.8rem; color:var(--text-muted); margin-top:0.25rem;">~$${r.estimatedCost || '?'} per person</p>
    </div>
  `).join('');

  return `
    <div class="day-card" id="day-card-${index}">
      <div class="day-card-header">
        <div class="day-number">${day.day}</div>
        <div class="day-info">
          <h3>${day.theme || `Day ${day.day}`}</h3>
          <p>${day.date || ''} ${day.dailyCostEstimate ? `• ~$${day.dailyCostEstimate} per person` : ''}</p>
        </div>
      </div>
      <div class="day-content">
        <!-- Activities Timeline -->
        <div class="info-section-title" style="margin-bottom:1rem;">🗓️ Day Plan</div>
        <div class="timeline">${activities || '<p style="color:var(--text-muted)">No activities listed.</p>'}</div>

        <!-- Hotel & Restaurants -->
        <div class="info-grid" style="margin-top:2rem;">
          <div>
            <div class="info-section-title">🏨 Where to Stay</div>
            ${hotel}
          </div>
          <div>
            <div class="info-section-title">🍽️ Where to Eat</div>
            ${restaurants || '<p style="color:var(--text-muted); font-size:0.85rem;">No restaurant info available.</p>'}
          </div>
        </div>
      </div>
    </div>
  `;
}

// ── Error State ────────────────────────────────────────────
function showError(msg) {
  document.getElementById('loading-state').style.display  = 'none';
  document.getElementById('itinerary-content').style.display = 'none';
  document.getElementById('error-state').style.display   = 'block';
  document.getElementById('error-msg').textContent        = msg;
}
